@@ -0,0 +1,16 @@
+import { createEventCard } from './event-card.js';
+
+export function mapEventsChronologically(events, project) {
+  return events
+    .map((event) => ({
+      event,
+      card: createEventCard(event),
+      timestamp: new Date(event.startsAt).getTime(),
+    }))
+    .sort((a, b) => a.timestamp - b.timestamp)
+    .map(({ event, card }) => project(event, card));
+}
+
+export function buildAgenda(events) {
+  return mapEventsChronologically(events, (_event, card) => card);
+}

